// i18n.js: languages. English is written in the code; this file maps English text to Russian
// and Armenian. Two ways to translate:
//   1) t('English text', {vars}) in code, for sentences built from pieces (numbers, names);
//   2) a translator that watches the page and replaces any text (and placeholders, titles,
//      aria-labels) that matches a dictionary entry exactly. So most pages need no code changes:
//      adding a line to the dictionary is enough.
// Missing entries simply stay in English. Loaded first, before core.js.
'use strict';

const LANGS = [['en', 'English'], ['ru', 'Русский'], ['hy', 'Հայերեն']];
let LANG = 'en';
try {
  const saved = localStorage.getItem('lumen.lang');
  const nav = (navigator.language || 'en').slice(0, 2);
  LANG = saved || (['ru', 'hy'].includes(nav) ? nav : 'en');
} catch { /* fine */ }
document.documentElement.lang = LANG;
const LOCALE = () => ({ ru: 'ru-RU', hy: 'hy-AM' }[LANG]);
// dates everywhere follow the chosen language (code that passes no locale gets ours)
if (LANG !== 'en') {
  for (const m of ['toLocaleDateString', 'toLocaleString', 'toLocaleTimeString']) {
    const orig = Date.prototype[m];
    Date.prototype[m] = function localized(locales, opts) { return orig.call(this, locales === undefined ? LOCALE() : locales, opts); };
  }
}

function setLang(l) {
  try { localStorage.setItem('lumen.lang', l); } catch { /* fine */ }
  location.reload();                       // simplest and safest: draw everything again in the new language
}

// ---------------------------------------------------------------- dictionary
const DICT = { ru: {}, hy: {} };
/** add(english, russian, armenian) */
const i18nAdd = (en, ru, hy) => { if (ru) DICT.ru[en] = ru; if (hy) DICT.hy[en] = hy; };

