// sentences with numbers inside: [pattern, russian, armenian] ($1, $2 = the numbers)
const PATTERNS = [
  [/^(\d+) days? streak$/, (n) => `${n} ${['день', 'дня', 'дней'][ruForm(n)]} подряд`, (n) => `${n} օր անընդմեջ`],
  [/^today counted ✓ · best (\d+)$/, (n) => `сегодня засчитано ✓ · рекорд ${n}`, (n) => `այսօրը հաշվված է ✓ · ռեկորդ ${n}`],
  [/^(\d+) more min today · best (\d+)$/, (n, b) => `ещё ${n} мин сегодня · рекорд ${b}`, (n, b) => `այսօր ևս ${n} րոպե · ռեկորդ ${b}`],
  [/^(\S+) to go$/, (n) => `осталось ${n}`, (n) => `մնաց ${n}`],
  [/^focused of (\S+) studied today$/, (n) => `в фокусе из ${n} сегодня`, (n) => `կենտրոնացած՝ այսօրվա ${n}-ից`],
  [/^(\d+) questions? to review$/, (n) => `${n} на повторение`, (n) => `${n} հարց կրկնելու`],
  [/^(\d+) scheduled for later$/, (n) => `${n} запланировано на потом`, (n) => `${n} պլանավորված է հետոյի համար`],
  [/^(\d+) lessons? · (\S+) studied$/, (n, s) => `${n} ${['урок', 'урока', 'уроков'][ruForm(n)]} · ${s} учёбы`, (n, s) => `${n} դաս · ${s} պարապմունք`],
];
function ruForm(n) { const f = new Intl.PluralRules('ru-RU').select(Number(n)); return f === 'one' ? 0 : f === 'few' ? 1 : 2; }
function translateText(key) {
  const D = DICT[LANG];
  if (D[key]) return D[key];
  for (const [re, ru, hy] of PATTERNS) { const m = key.match(re); if (m) return (LANG === 'ru' ? ru : hy)(...m.slice(1)); }
  return null;
}

