// units: [one, few, many] for Russian (Armenian nouns stay singular after numbers)
const UNITS = {
  lesson: [['урок', 'урока', 'уроков'], 'դաս'], 'focused minute': [['минута фокуса', 'минуты фокуса', 'минут фокуса'], 'կենտրոնացած րոպե'],
  minute: [['минута', 'минуты', 'минут'], 'րոպե'], 'eye rest': [['отдых для глаз', 'отдыха для глаз', 'отдыхов для глаз'], 'աչքերի հանգիստ'],
  card: [['карточка', 'карточки', 'карточек'], 'քարտ'], day: [['день', 'дня', 'дней'], 'օր'], week: [['неделя', 'недели', 'недель'], 'շաբաթ'],
  quest: [['задание', 'задания', 'заданий'], 'առաջադրանք'], time: [['раз', 'раза', 'раз'], 'անգամ'], min: [['мин', 'мин', 'мин'], 'րոպե'],
  'eye rests': [['отдых для глаз', 'отдыха для глаз', 'отдыхов для глаз'], 'աչքերի հանգիստ'], cards: [['карточка', 'карточки', 'карточек'], 'քարտ'],
  question: [['вопрос', 'вопроса', 'вопросов'], 'հարց'],
};
const ruPlural = new Intl.PluralRules('ru-RU');
/** "lesson", 3 -> "lessons" / "урока" / "դաս" */
function tUnit(unit, n) {
  const u = UNITS[unit];
  if (LANG === 'ru' && u) { const f = ruPlural.select(n); return u[0][f === 'one' ? 0 : f === 'few' ? 1 : 2]; }
  if (LANG === 'hy' && u) return u[1];
  return n === 1 || /s$/.test(unit) ? unit : `${unit}s`;
}

/** Translate one English text (with optional {vars}). Unknown text stays English. */
function t(en, vars) {
  if (en == null) return '';
  let s = (DICT[LANG] && DICT[LANG][en]) || en;
  if (vars) s = s.replace(/\{(\w+)\}/g, (m, k) => (vars[k] !== undefined ? vars[k] : m));
  return s;
}

