// ---------------------------------------------------------------- the page translator
// Watches the whole page; every new or changed text that matches a dictionary entry exactly
// (ignoring spaces around it) is swapped. Text written by the user (notes, chat, cards) is left alone.
(() => {
  if (LANG === 'en') return;
  const D = DICT[LANG];
  const SKIP = 'script,style,textarea,.md,.msg,.notegrid,.fl-face,.qtile h3,[data-noi18n]';     // text written by the user
  const ATTRS = ['placeholder', 'title', 'aria-label'];
  const fix = (node) => {
    if (node.nodeType === 3) {
      const raw = node.nodeValue, key = raw.trim();
      if (!key || (node.parentElement && node.parentElement.closest(SKIP))) return;
      const tr = translateText(key);
      if (tr) node.nodeValue = raw.replace(key, tr);
      return;
    }
    if (node.nodeType !== 1 || node.closest(SKIP)) return;
    for (const a of ATTRS) { const v = node.getAttribute(a); if (v && D[v.trim()]) node.setAttribute(a, D[v.trim()]); }
    const walker = document.createTreeWalker(node, NodeFilter.SHOW_TEXT | NodeFilter.SHOW_ELEMENT);
    let n = walker.nextNode();
    while (n) {
      if (n.nodeType === 3) fix(n);
      else if (n.matches && n.matches(SKIP)) { n = walker.nextSibling() || walker.nextNode(); continue; }
      else for (const a of ATTRS) { const v = n.getAttribute(a); if (v && D[v.trim()]) n.setAttribute(a, D[v.trim()]); }
      n = walker.nextNode();
    }
  };
  const start = () => {
    fix(document.body);
    new MutationObserver((muts) => {
      for (const m of muts) {
        if (m.type === 'characterData') fix(m.target);
        else m.addedNodes.forEach(fix);
      }
    }).observe(document.body, { childList: true, subtree: true, characterData: true });
  };
  if (document.body) start(); else document.addEventListener('DOMContentLoaded', start);
})();
